<template>
  <main class="page">
    <header><div><h2>Labores agrícolas</h2><p>Plantillas reutilizables; el centro de costo se selecciona en cada actividad del plan.</p></div><button class="primary" @click="nuevo">+ Nueva labor</button></header>
    <section class="toolbar"><input v-model.trim="filtro" placeholder="Buscar por código o labor"><label><input v-model="soloActivas" type="checkbox"> Solo activas</label></section>
    <section class="card"><p v-if="cargando" class="empty">Cargando labores…</p><p v-else-if="filtradas.length === 0" class="empty">No hay labores definidas.</p><div v-else class="table-wrap"><table><thead><tr><th>Código</th><th>Labor</th><th>Cultivo</th><th>U/M</th><th>Norma / U</th><th>Nivel de actividad</th><th>Índice permisible</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="labor in filtradas" :key="labor.id"><td>{{ labor.codigo }}</td><td><strong>{{ labor.nombre }}</strong></td><td>{{ cultivoNombre(labor.tipoCultivoId) }}</td><td>{{ labor.unidadMedida }}</td><td class="amount">{{ labor.normaPorUnidad || '—' }}</td><td>{{ labor.nivelActividad || '—' }}</td><td class="amount">{{ labor.indiceConsumo ?? '—' }}</td><td><span :class="labor.activo ? 'active' : 'inactive'">{{ labor.activo ? 'Activa' : 'Inactiva' }}</span></td><td class="actions"><button class="secondary" @click="editar(labor)">Editar</button><button class="danger" @click="eliminar(labor)">Eliminar</button></td></tr></tbody></table></div></section>

    <div v-if="modal" class="overlay" @click.self="modal = false"><section class="modal"><header><div><h3>{{ editando ? 'Editar labor' : 'Nueva labor agrícola' }}</h3><p>Los trabajadores y salarios se definen directamente en cada plan mensual.</p></div><button class="close" @click="modal = false">×</button></header><div class="body"><div class="grid"><label><span class="field-label">Código *<span class="help" title="Identificador corto para reconocer la labor en los planes y reportes.">?</span></span><input v-model.trim="form.codigo" maxlength="30"></label><label><span class="field-label">Nombre *<span class="help" title="Nombre descriptivo de la actividad agrícola que se realizará.">?</span></span><input v-model.trim="form.nombre" maxlength="150"></label><label><span class="field-label">Cultivo aplicable<span class="help" title="Opcional. Limita esta labor a un cultivo; deje “Todos” si puede usarse con cualquiera.">?</span></span><select v-model="form.tipoCultivoId"><option value="">Todos</option><option v-for="cultivo in cultivos" :key="cultivo.id" :value="cultivo.id">{{ cultivo.nombre }}</option></select></label><label><span class="field-label">Unidad de medida *<span class="help" title="Cómo se mide la labor: ha para siembra o deshierbe, t para cosecha, kg o u según corresponda.">?</span></span><input v-model.trim="form.unidadMedida" placeholder="ha"></label><label><span class="field-label">Norma por unidad<span class="help" title="Opcional. Rendimiento o cantidad esperada por cada unidad de medida de la labor.">?</span></span><input v-model.number="form.normaPorUnidad" min="0" step="0.0001" type="number"></label><label><span class="field-label">Nivel de actividad<span class="help" title="Base con la que se mide el consumo de combustible, por ejemplo: ha trabajadas, km recorridos u horas de máquina.">?</span></span><input v-model.trim="form.nivelActividad" maxlength="100" placeholder="ha trabajadas"></label><label><span class="field-label">Índice permisible<span class="help" title="Valor técnico máximo permitido de combustible por cada nivel de actividad; por ejemplo, litros por ha trabajada.">?</span></span><input v-model.number="form.indiceConsumo" min="0" step="0.0001" type="number"></label></div><label class="description"><span class="field-label">Descripción<span class="help" title="Opcional. Aclare el alcance, método o condición especial de la labor.">?</span></span><textarea v-model.trim="form.descripcion" rows="2" maxlength="500"/></label><label class="check"><input v-model="form.activo" type="checkbox"> Labor activa<span class="help" title="Las labores inactivas se conservan históricamente, pero no estarán disponibles para nuevos planes.">?</span></label></div><footer><button class="secondary" @click="modal = false">Cancelar</button><button class="primary" :disabled="guardando" @click="guardar">{{ guardando ? 'Guardando…' : 'Guardar' }}</button></footer></section></div>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useNotification } from '@/composables/useNotification'
import TipoCultivoService from '@/services/TipoCultivoService'
import LaborAgricolaService from '@/services/LaborAgricolaService'
import type { TipoCultivo } from '@/types/TipoCultivo'
import type { LaborAgricola, LaborAgricolaRequest } from '@/types/LaborAgricola'

const notify = useNotification(); const labores = ref<LaborAgricola[]>([]); const cultivos = ref<TipoCultivo[]>([])
const cargando = ref(false); const guardando = ref(false); const modal = ref(false); const editando = ref<LaborAgricola | null>(null); const filtro = ref(''); const soloActivas = ref(true)
const nuevoForm = (): LaborAgricolaRequest => ({ codigo: '', nombre: '', descripcion: '', tipoCultivoId: '', unidadMedida: 'ha', normaPorUnidad: 0, nivelActividad: '', indiceConsumo: undefined, activo: true, dotaciones: [] })
const form = reactive<LaborAgricolaRequest>(nuevoForm())
const filtradas = computed(() => { const q = filtro.value.toLowerCase(); return labores.value.filter(l => (!soloActivas.value || l.activo) && (!q || `${l.codigo} ${l.nombre}`.toLowerCase().includes(q))) })
const cultivoNombre = (id?: string) => cultivos.value.find(cultivo => cultivo.id === id)?.nombre || 'Todos'
function nuevo () { editando.value = null; Object.assign(form, nuevoForm()); modal.value = true }
function editar (labor: LaborAgricola) { editando.value = labor; Object.assign(form, { codigo: labor.codigo, nombre: labor.nombre, descripcion: labor.descripcion || '', tipoCultivoId: labor.tipoCultivoId || '', unidadMedida: labor.unidadMedida, normaPorUnidad: labor.normaPorUnidad || 0, nivelActividad: labor.nivelActividad || '', indiceConsumo: labor.indiceConsumo, activo: labor.activo, dotaciones: [] }); modal.value = true }
async function cargar () { cargando.value = true; try { labores.value = await LaborAgricolaService.listar() } catch (error) { console.error(error); notify.error('Labores agrícolas', 'No se pudieron cargar las labores.') } finally { cargando.value = false } }
async function guardar () { if (!form.codigo || !form.nombre || !form.unidadMedida) { notify.warning('Datos incompletos', 'Indique código, nombre y unidad de medida.'); return } guardando.value = true; try { if (editando.value) await LaborAgricolaService.actualizar(editando.value.id, form); else await LaborAgricolaService.crear(form); modal.value = false; await cargar(); notify.success('Labor agrícola', 'La plantilla fue guardada.') } catch (error) { console.error(error); notify.error('Labor agrícola', 'No se pudo guardar la plantilla.') } finally { guardando.value = false } }
async function eliminar (labor: LaborAgricola) { if (!window.confirm(`¿Eliminar la labor agrícola "${labor.nombre}"?`)) return; try { await LaborAgricolaService.eliminar(labor.id); await cargar(); notify.success('Labor agrícola', 'La plantilla fue eliminada.') } catch (error) { console.error(error); notify.error('Labor agrícola', 'No se pudo eliminar la plantilla.') } }
onMounted(async () => { try { cultivos.value = (await TipoCultivoService.getAll()).filter(c => c.activo) } catch (error) { console.error(error); notify.error('Catálogos', 'No se pudieron cargar los catálogos de labores.') } await cargar() })
</script>

<style scoped>
.page{margin:0 auto;max-width:1350px;padding:1.5rem}.page>header,.detail,footer{align-items:center;display:flex;gap:1rem;justify-content:space-between}.page h2{color:#1e3a5f;margin:0}.page p{color:#64748b}.toolbar,.card{background:#fff;border:1px solid #dbe4ea;border-radius:10px;margin-top:1rem;padding:1rem}.toolbar{display:flex;gap:1rem}.toolbar input[type=text],.toolbar input:not([type]){min-width:320px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #e2e8f0;padding:.7rem;text-align:left}th{background:#f1f5f9;font-size:.75rem;text-transform:uppercase}td small{color:#64748b;display:block;margin-top:.2rem}.amount{text-align:right}.actions{display:flex;gap:.5rem}.primary,.secondary,.danger,.close{border:0;border-radius:6px;cursor:pointer;padding:.55rem .8rem}.primary{background:#1d4ed8;color:#fff}.secondary{background:#e2e8f0;color:#334155}.danger{background:#fee2e2;color:#b91c1c}.active,.inactive{border-radius:99px;font-size:.75rem;font-weight:700;padding:.25rem .5rem}.active{background:#dcfce7;color:#166534}.inactive{background:#e2e8f0;color:#475569}.empty{padding:2rem;text-align:center}.overlay{align-items:center;background:#0f172a8c;display:flex;inset:0;justify-content:center;padding:1rem;position:fixed;z-index:1000}.modal{background:#fff;border-radius:12px;display:flex;flex-direction:column;max-height:94vh;max-width:980px;width:100%}.modal header,.modal footer{border-bottom:1px solid #e2e8f0;padding:1rem 1.25rem}.modal footer{border-bottom:0;border-top:1px solid #e2e8f0}.modal h3{margin:0}.close{background:transparent;font-size:2rem;line-height:1}.body{overflow:auto;padding:1.25rem}.grid{display:grid;gap:1rem;grid-template-columns:repeat(3,1fr)}label{display:grid;font-size:.8rem;font-weight:700;gap:.3rem}.field-label{align-items:center;display:flex;gap:.35rem}.help{align-items:center;background:#1d4ed8;border-radius:50%;color:#fff;cursor:help;display:inline-flex;font-size:.68rem;height:1rem;justify-content:center;line-height:1;width:1rem}input,select,textarea{border:1px solid #cbd5e1;border-radius:6px;box-sizing:border-box;padding:.55rem;width:100%}.description{margin:1rem 0}.detail{margin:1rem 0}.check{align-items:center;display:flex;margin-top:1rem}.check input{width:auto}@media(max-width:750px){.page>header,.toolbar{align-items:stretch;flex-direction:column}.grid{grid-template-columns:1fr}}
</style>
